{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Encorafenib, which contains a methyl carbamate and a heteroaromatic core similar to the query's carbamate-bearing scaffold, has a human oral bioavailability of 85%, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib, featuring a pyrrolidine carboxamide directly attached to a heteroaryl like the query's proline-heteroaryl motif, has an absolute oral bioavailability of 25.3% in healthy subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Tazemetostat, a large, lipophilic, and polar molecule, has a median absolute oral bioavailability of 31.8% in patients in the fasted state, demonstrating that high molecular weight and TPSA do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alpelisib, containing a pyrrolidine carboxamide and heteroaromatic thiazole, has an oral bioavailability of 68.7% in healthy subjects, supporting good absorption for proline-amide-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Golidocitinib, a heteroaryl amide with high structural transferability, has >80% oral bioavailability in humans, further supporting high oral bioavailability for this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All highly transferable experimental analogues show absolute oral bioavailability above 20%, including structurally relevant carbamate- and proline-amide-containing drugs. The physicochemical prior is therefore overridden by consistent human PK evidence, supporting F ≥ 20% for the query.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query or a closely matched dimeric/PROTAC-like analogue.",
    "The query is substantially larger and more lipophilic than the experimental analogues, so the magnitude of F is uncertain even though the threshold direction is supported."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

